from pathlib import Path
import json, hashlib
ROOT=Path(__file__).resolve().parents[1]
PUB=ROOT/'public'
OUT=ROOT/'private/gold'

def ref(path, text, end=None, units=None):
    p=PUB/path
    lines=p.read_text().splitlines()
    idx=next(i for i,x in enumerate(lines) if text in x)
    last=idx
    if end:
        last=next(i for i in range(idx,len(lines)) if end in lines[i])
    obj={'file':path,'line_start':idx+1,'line_end':last+1,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
    if units: obj['units']=units
    return obj

def doc(name, text, end=None, units=None):
    paths=list((PUB/'shared/rawdocs').rglob(name))
    assert len(paths)==1,(name,paths)
    return ref(str(paths[0].relative_to(PUB)),text,end,units)

def fact(id,dim,points,expected,refs,accept=None,reject=None,units=None):
    return {'id':id,'dimension':dim,'points':points,'expected':expected,'sources':refs,
            'accept':accept or [],'reject':reject or [],'units':units or 'as stated in expected fact'}

A='algorithm_strategy';E='execution';H='hardware'
def save(cid,title,facts,critical,unknown):
    for dim in [A,E,H]: assert sum(f['points'] for f in facts if f['dimension']==dim)==10,(cid,dim)
    o={'schema':'aprof.code-understanding-gold/v1','case':cid,'title_private':title,'max_score':30,
       'dimensions':{A:10,E:10,H:10},'facts':facts,'critical_errors':critical,'acceptable_unknowns':unknown,
       'grading':'Use private/GRADING_PROTOCOL.md; do not infer unsupported measurements or penalize brevity.'}
    (OUT/(cid+'.json')).write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n')

def c(id,dim,cap,trigger):return {'id':id,'dimension':dim,'cap':cap,'explicit_claim_trigger':trigger,'omission_does_not_trigger':True}

