save('case-06','Identifier transfer and platform boundary without broad portability claims',[
 fact('CU06.A01',A,3,'Entry V is the same unary y=2^(0.5*x-1) mathematical transform. BF16 is converted to float for Muls/Adds/Exp and converted back with CAST_RINT. Neutral identifiers do not change this computation.',[ref(vt,'t.gain =','t.bias ='),ref(vk,'auto fi =','AscendC::Cast(out, fo, mode, count);')]),
 fact('CU06.A02',A,3,'Entry C is the same half-input matmul followed by half-output LeakyRelu, slope approximately 0.001, with float accumulation followed by half Fixpipe storage before Vector activation. It has the same one-tile-per-AIC and paired AIV split.',[ref(cm,'AscendC::Mmad(bufOpal0'),ref(cm,'AscendC::FixpipeParamsV220'),ref(cm,'AscendC::LeakyRelu(bufOpalV')]),
 fact('CU06.A03',A,4,'The recorded test delta changes identifiers and include filenames only; shape/tile constants, datatype/API calls and control flow are preserved. Therefore renaming is not evidence of a new algorithm, a new buffer count or a new synchronization scheme. V and C are separate entries with separate outputs.',[ref('case-06/source/DELTA.json','"numeric_constants_changed": false'),ref('case-06/source/DELTA.json','"api_calls_changed": false')]),
 fact('CU06.E01',E,4,'V launches 3 blocks with laneExtent=8340/windowElements=4096; element starts [0,8340,16680], lengths [8340,8340,8339], tail counts [148,148,147]. It retains single input/output slots and 49152 explicit UB bytes for BF16.',[ref(vt,'t.laneCount =', 't.windowElements ='),ref(vk,'const uint64_t offset', 'y_.SetGlobalBuffer'),ref(vk,'const uint32_t rawBytes', 'pipe_.InitBuffer(fpOut_, fpBytes);')]),
 fact('CU06.E02',E,3,'C still has 2 AIC and 4 AIV under __mix__(1,2); AIC C starts [0,32768] half elements and AIV C starts [0,16384,32768,49152], each AIV 16384 elements. Renamed ApplyGate still computes the same GM offsets.',[ref(cm,'__global__ __mix__(1, 2)'),ref(cm,'dstOpal = dstOpal[AscendC::GetBlockIdx() / 2'),ref(cm,'uint32_t gmOffset'),ref(cm,'ApplyGate(bufOpalV')]),
 fact('CU06.E03',E,3,'C preserves the physical path GM half ND -> L1 half NZ -> L0A/L0B half -> float NZ L0C -> half ND GM -> UB half -> same GM regions. Vector V uses raw BF16 queues plus FP32 scratch. No renamed tensor is a new memory allocation merely because its name differs.',[ref(cm,'bufQuartz1 =', 'bufOpal0 ='),ref(cm,'bufOpalV ='),ref(vk,'pipe_.InitBuffer(inQ_', 'pipe_.InitBuffer(fpOut_, fpBytes);')]),
 fact('CU06.H01',H,3,'910C/A3 selects 2201 according to the fixed platform contract. 3510 is Ascend 950PR/950DT in these documents. A macro guard or common API name cannot establish that 3510 behavior ran on the 910C target.',[doc('simd_builtin_keywords.md','- Ascend 950PR&950DT系列产品：3510'),doc('simd_builtin_keywords.md','- Atlas A3系列产品：2201'),ref(cm,'#if defined(__NPU_ARCH__) && (__NPU_ARCH__ == 2201)')]),
 fact('CU06.H02',H,3,'For C A input, 2201 loops LoadData2DParams to convert NZ L1 to Zz L0A; 3510 calls LoadData2DParamsV2 to load NZ L1 to NZ L0A. The actual packed A representation and parameter structure differ across branches; one branch must not be assigned to both targets.',[ref(cm,'#if defined(__NPU_ARCH__)', '#elif defined(__NPU_ARCH__)'),ref(cm,'#elif defined(__NPU_ARCH__) && (__NPU_ARCH__ == 3510)', '// B矩阵L1->L0B')]),
 fact('CU06.H03',H,2,'Both C branches express the B NZ->Zn route with transpose=true, but 2201 uses looped LoadData2DParams and 3510 uses LoadData2DParamsV2. Mmad, Fixpipe to GM and the subsequent mixed-core activation are outside that load branch and preserve the source-level logical pipeline.',[ref(cm,'// B矩阵L1->L0B（Nz->Zn）', '#elif'),ref(cm,'// B矩阵L1->L0B调用LoadData接口 + LoadData2DParamsV2', '#endif'),ref(cm,'AscendC::Mmad(bufOpal0')]),
 fact('CU06.H04',H,2,'Platform contracts have behavioral boundaries beyond identifier compatibility: for example CrossCoreWaitFlag blocks all following pipelines on A3/A2 despite the optional pipe argument, whereas 3510/950 uses the configured blocking pipeline. Both source branches may be explained statically, but neither new platform compilation nor comparative performance is verified.',[doc('CrossCoreWaitFlag_ISASI.md','无论`pipe`取值为何'),doc('CrossCoreWaitFlag_ISASI.md','`pipe`作为硬件指令的输入')],accept=['Another precise platform-specific contract boundary from the fixed files, while keeping the main load layout difference and uncertainty.'])
],[c('CU06.C01',H,2,'Maps 910C/A3 to 3510 or claims 2201 and 3510 physical A layouts are identical.'),c('CU06.C02',A,2,'Treats identifier renaming as changing the mathematical operation or adds a new fusion/reduction.'),c('CU06.C03',H,2,'Claims code existence proves cross-architecture compilation, timing or deployment compatibility.')],['Exact compiler acceptance for 3510 is not assumed; all 3510 discussion is static.','No requirement to assert the original source is invalid on 3510.','Equivalent concise description may refer to structure without repeating every original symbol name.'])
